#!/usr/bin/env bash
# Question 17: StatefulSet ${Q17_STS} is not healthy. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

if ! kubectl -n local-path-storage get deployment local-path-provisioner >/dev/null 2>&1; then
  [[ -f /opt/cka/addons/local-path-storage.yaml ]] || { echo "these lab images have no local-path provisioner: run ./cka images extras (or rebuild the images)" >&2; exit 1; }
  kubectl apply -f /opt/cka/addons/local-path-storage.yaml >/dev/null
fi
kubectl -n local-path-storage rollout status deployment/local-path-provisioner --timeout=180s >/dev/null
kubectl get storageclass local-path >/dev/null 2>&1 || kubectl apply -f /opt/cka/addons/local-path-storage.yaml >/dev/null
kubectl create namespace "${Q17_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q17_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q17_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q17_NS}" delete statefulset "${Q17_STS}" --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q17_NS}" delete service "${Q17_STS}-hl" --ignore-not-found >/dev/null
kubectl -n "${Q17_NS}" wait --for=delete pod -l app="${Q17_STS}" --timeout=90s >/dev/null 2>&1 || true
kubectl -n "${Q17_NS}" delete pvc -l app="${Q17_STS}" --ignore-not-found --wait=true >/dev/null
# Faults append assignments here (class=..., probe=...), read back after the break: a file,
# because a layered question runs each fault in its own subshell.
: > "/var/tmp/cka-q17.sts"

(
case "${Q17_FAULT}" in
  headless-clusterip)
    echo cip= >> "/var/tmp/cka-q17.sts"
    ;;
  service-selector)
    echo "selector=${Q17_STS}-db" >> "/var/tmp/cka-q17.sts"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
case "${Q17_FAULT_2}" in
  servicename-mismatch)
    echo "service=${Q17_STS}-headless" >> "/var/tmp/cka-q17.sts"
    ;;
  claim-class-typo)
    echo class=local-storage >> "/var/tmp/cka-q17.sts"
    ;;
  readiness-forced-rollback)
    echo probe=/healthz >> "/var/tmp/cka-q17.sts"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
)

(
cip=None selector=${Q17_STS} service=${Q17_STS}-hl class=local-path probe=/
. "/var/tmp/cka-q17.sts"
kubectl apply -f - <<< '{"apiVersion":"v1","kind":"Service","metadata":{"name":"'"${Q17_STS}"'-hl","namespace":"'"${Q17_NS}"'"},"spec":{"clusterIP":"'"$cip"'","selector":{"app":"'"$selector"'"},"ports":[{"name":"web","port":80}]}}' >/dev/null
kubectl apply -f - <<< '{"apiVersion":"apps/v1","kind":"StatefulSet","metadata":{"name":"'"${Q17_STS}"'","namespace":"'"${Q17_NS}"'"},"spec":{"serviceName":"'"$service"'","replicas":3,"selector":{"matchLabels":{"app":"'"${Q17_STS}"'"}},"template":{"metadata":{"labels":{"app":"'"${Q17_STS}"'"}},"spec":{"containers":[{"name":"nginx","image":"nginx:1.27-alpine","ports":[{"name":"web","containerPort":80}],"readinessProbe":{"httpGet":{"path":"'"$probe"'","port":80},"periodSeconds":5},"volumeMounts":[{"name":"data","mountPath":"/data"}]}]}},"volumeClaimTemplates":[{"metadata":{"name":"data"},"spec":{"accessModes":["ReadWriteOnce"],"storageClassName":"'"$class"'","resources":{"requests":{"storage":"100Mi"}}}}]}}' >/dev/null
if [[ "$class" == local-path && "$probe" == / ]]; then
  kubectl -n "${Q17_NS}" rollout status "statefulset/${Q17_STS}" --timeout=240s >/dev/null 2>&1 || true
fi
# Pod 0's claim holds data once it is Bound: record it, so that deleting it shows.
uid=''
if [[ "$class" == local-path ]]; then
  for _ in $(seq 1 60); do
    if [[ "$(kubectl -n "${Q17_NS}" get pvc "data-${Q17_STS}-0" -o jsonpath='{.status.phase}' 2>/dev/null)" == Bound ]]; then
      uid=$(kubectl -n "${Q17_NS}" get pvc "data-${Q17_STS}-0" -o jsonpath='{.metadata.uid}')
      break
    fi
    sleep 2
  done
fi
[[ -n "$uid" ]] || uid=none
echo "$uid" > "/var/tmp/cka-q17.uid"
chmod 644 "/var/tmp/cka-q17.uid"
)

(
case "${Q17_FAULT_2}" in
  servicename-mismatch) ;;
  claim-class-typo)
    for _ in $(seq 1 15); do
      [[ "$(kubectl -n "${Q17_NS}" get pvc "data-${Q17_STS}-0" -o jsonpath='{.status.phase}' 2>/dev/null)" == Pending ]] && break
      sleep 2
    done
    ;;
  readiness-forced-rollback)
    notready=0
    for _ in $(seq 1 10); do
      states="$(kubectl -n "${Q17_NS}" get pods -l "app=${Q17_STS}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
      if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
      if kubectl -n "${Q17_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
      if grep -qE '^Running False' <<< "$states"; then
        notready=$((notready + 1))
        (( notready >= 3 )) && break
      else
        notready=0
      fi
      sleep 2
    done
    ;;
esac
)
